package mathutils

import "testing"

// Definisi slice of structs untuk Table-Driven Test
func TestCalculateDiscount(t *testing.T) {
  tests := []struct {
    name     string
    price    float64
    discount float64
    expected float64
  }{
    {"Valid Discount", 100.0, 20.0, 80.0},
    {"Zero Discount", 50.0, 0.0, 50.0},
    {"Max Discount", 200.0, 100.0, 0.0},
  }

  for _, tt := range tests {
    t.Run(tt.name, func(t *testing.T) {
      result := CalculateDiscount(tt.price, tt.discount)
      if result != tt.expected {
        t.Errorf("got %v, want %v", result, tt.expected)
      }
    })
  }
}

