import http from "k6/http";
import { check, sleep } from "k6";

// Simulasikan 50 pengguna virtual selama 30 detik
export const options = {
  vus: 50,
  duration: "30s",
  thresholds: {
    http_req_duration: ["p(95)<500"], // 95% request harus < 500ms
    http_req_failed:   ["rate<0.01"], // error rate < 1%
  },
};

export default function () {
  const res = http.get("https://api.contoh.com/products");
  check(res, {
    "status 200":       (r) => r.status === 200,
    "respons < 500ms":  (r) => r.timings.duration < 500,
  });
  sleep(1); // jeda antar-iterasi seperti pengguna nyata
}
